#!/bin/bash\n\n#############################################################################\n# Supabase Edge Functions Environment Variables Setup Script\n#############################################################################\n# This script sets the required environment variables for Edge Functions\n# These variables are stored in Supabase and accessed by the functions via Deno.env.get()\n#\n# Required Environment Variables:\n#   - CRB_API_KEY: TransUnion Credit Reference Bureau API key\n#   - PAYROLL_API_KEY: Payroll provider API key\n#\n# Usage:\n#   chmod +x scripts/set-env-vars.sh\n#   ./scripts/set-env-vars.sh\n#\n# Prerequisites:\n#   1. Supabase CLI must be installed\n#   2. Must be logged into Supabase: supabase login\n#   3. Project must be linked: supabase link --project-ref <ref>\n#############################################################################\n\nset -e\n\necho \"🔐 Supabase Edge Functions - Environment Variables Setup\"\necho \"========================================================\"\necho \"\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Check if Supabase CLI is installed\nif ! command -v supabase &> /dev/null; then\n    echo -e \"${RED}❌ Supabase CLI is not installed${NC}\"\n    echo \"Install it with: npm install -g supabase\"\n    exit 1\nfi\n\necho -e \"${GREEN}✓ Supabase CLI found${NC}\"\necho \"\"\n\n# Function to set environment variable\nset_env_var() {\n    local key=$1\n    local prompt=$2\n    local current_value=$3\n\n    echo -e \"${YELLOW}📝 Setting ${key}${NC}\"\n    echo \"$prompt\"\n    \n    if [ -n \"$current_value\" ]; then\n        echo -e \"Current value: ${BLUE}[***hidden***]${NC}\"\n        read -p \"Enter new value (press Enter to keep current): \" new_value\n        if [ -z \"$new_value\" ]; then\n            echo -e \"${GREEN}✓ Keeping existing value for ${key}${NC}\"\n            return\n        fi\n        value=\"$new_value\"\n    else\n        read -p \"Enter value: \" value\n        if [ -z \"$value\" ]; then\n            echo -e \"${RED}❌ Value cannot be empty${NC}\"\n            return 1\n        fi\n    fi\n    \n    # Set the environment variable in Supabase\n    echo \"Setting ${key} in Supabase...\"\n    supabase secrets set \"${key}=${value}\" --project-ref=\"$(supabase projects list --json | jq -r '.[0].id')\"\n    \n    if [ $? -eq 0 ]; then\n        echo -e \"${GREEN}✓ ${key} set successfully${NC}\"\n    else\n        echo -e \"${RED}❌ Failed to set ${key}${NC}\"\n        return 1\n    fi\n    echo \"\"\n}\n\necho -e \"${YELLOW}This script will guide you through setting environment variables for Edge Functions.${NC}\"\necho \"\"\n\n# Set CRB_API_KEY\nset_env_var \"CRB_API_KEY\" \\\n    \"Enter your TransUnion CRB API key (used by crb-check function):\" \\\n    \"\"\n\nif [ $? -ne 0 ]; then\n    exit 1\nfi\n\n# Set PAYROLL_API_KEY\nset_env_var \"PAYROLL_API_KEY\" \\\n    \"Enter your Payroll Provider API key (used by payroll-integration function):\" \\\n    \"\"\n\nif [ $? -ne 0 ]; then\n    exit 1\nfi\n\necho \"\"\necho -e \"${GREEN}✅ All environment variables configured!${NC}\"\necho \"\"\necho -e \"${BLUE}Verification:${NC}\"\necho \"To view current secrets (values are hidden), run:\"\necho -e \"${YELLOW}supabase secrets list${NC}\"\necho \"\"\necho -e \"${BLUE}Note:${NC}\"\necho \"- Secrets are stored encrypted in Supabase\"\necho \"- They are NOT stored in version control\"\necho \"- Edge Functions access them via Deno.env.get('KEY_NAME')\"\necho \"- Changes take effect on the next function deployment\"\necho \"\"\n"